public class Alumno {
    private String nombre;
    private String email;
    private double notaMedia;

    public Alumno(String nombre, String email) {
        setNombre(nombre);  // Reutilizamos la validacion del setter
        setEmail(email);
        this.notaMedia = 0.0;
    }

    // --- Getters (solo lectura) ---
    public String getNombre() { return nombre; }
    public String getEmail() { return email; }
    public double getNotaMedia() { return notaMedia; }

    // --- Setters (con validacion) ---
    public void setNombre(String nombre) {
        if (nombre == null || nombre.isBlank()) {
            throw new IllegalArgumentException("El nombre no puede estar vacio");
        }
        this.nombre = nombre.trim();
    }

    public void setEmail(String email) {
        if (email == null || !email.contains("@")) {
            throw new IllegalArgumentException("Email invalido: " + email);
        }
        this.email = email.trim().toLowerCase();
    }

    public void setNotaMedia(double notaMedia) {
        if (notaMedia < 0 || notaMedia > 10) {
            throw new IllegalArgumentException("La nota debe estar entre 0 y 10");
        }
        this.notaMedia = notaMedia;
    }

    // --- Metodos de accion ---
    public boolean estaAprobado() {
        return notaMedia >= 5.0;
    }

    public String getCalificacion() {
        if (notaMedia >= 9) return "Sobresaliente";
        if (notaMedia >= 7) return "Notable";
        if (notaMedia >= 5) return "Aprobado";
        return "Suspenso";
    }

    @Override
    public String toString() {
        return nombre + " (" + email + ") - Nota: " + String.format("%.1f", notaMedia);
    }
}

