public class CuentaBancaria {
    private String titular;
    private double saldo;

    public CuentaBancaria(String titular, double saldoInicial) {
        if (titular == null || titular.isBlank()) throw new IllegalArgumentException("Titular invalido");
        if (saldoInicial < 0) throw new IllegalArgumentException("Saldo no puede ser negativo");
        this.titular = titular;
        this.saldo = saldoInicial;
    }

    public String getTitular() { return titular; }
    public double getSaldo() { return saldo; }

    // Sin setter de saldo: solo se modifica con ingresar/retirar
    public void ingresar(double cantidad) {
        if (cantidad <= 0) throw new IllegalArgumentException("Cantidad debe ser positiva");
        saldo += cantidad;
    }

    public void retirar(double cantidad) {
        if (cantidad <= 0) throw new IllegalArgumentException("Cantidad debe ser positiva");
        if (cantidad > saldo) throw new IllegalArgumentException("Saldo insuficiente");
        saldo -= cantidad;
    }

    public static void main(String[] args) {
        CuentaBancaria c = new CuentaBancaria("Ana", 1000);
        c.ingresar(500);
        c.retirar(200);
        System.out.println(c.getTitular() + ": " + c.getSaldo() + " EUR");
    }
}

