public class Alumno {
    private String nombre;
    private String email;
    private double notaMedia;
    private static int totalAlumnos = 0;  // Contador compartido

    public Alumno(String nombre, String email) {
        this.nombre = nombre;
        this.email = email;
        this.notaMedia = 0.0;
        totalAlumnos++;  // Se incrementa con cada nuevo alumno
    }

    // Metodo estatico: puede acceder a totalAlumnos
    public static int getTotalAlumnos() {
        return totalAlumnos;
    }

    // Metodo estatico de utilidad: no necesita datos de un alumno concreto
    public static boolean esAprobado(double nota) {
        return nota >= 5.0;
    }

    // Metodos de instancia
    public String getNombre() { return nombre; }
    public double getNotaMedia() { return notaMedia; }
    public void setNotaMedia(double nota) { this.notaMedia = nota; }

    public static void main(String[] args) {
        System.out.println("Alumnos creados: " + Alumno.getTotalAlumnos());

        Alumno a1 = new Alumno("Ana", "ana@email.com");
        Alumno a2 = new Alumno("Carlos", "carlos@email.com");

        System.out.println("Alumnos creados: " + Alumno.getTotalAlumnos()); // 2

        // Metodo estatico sin crear objeto
