        System.out.println("Nota 4 es aprobada: " + Alumno.esAprobado(4.0));
    }
}

Una **constante** es un valor que no cambia nunca. En Java se define con `static final`:

```java
public static final int MAXIMO_ALUMNOS = 30;
public static final double IVA = 21.0;
public static final String NOMBRE_CICLO = "DAM/DAW";
```

**Por qué `static final`?**
- `static`: la constante pertenece a la clase, no a un objeto. No necesitas crear un objeto para acceder a ella.
- `final`: el valor no puede cambiar una vez asignado. Si intentas modificarlo, el compilador da error.

**Convención**: las constantes se escriben en `SCREAMING_SNAKE_CASE` (todo en mayúsculas con guiones bajos).

```java
// Correcto
public static final int MAXIMO_REINTENTOS = 3;

// Incorrecto
public static final int maximoReintentos = 3; // No sigue la convencion
```

public class Alumno {
    // --- Constantes (static final) ---
    public static final double NOTA_MINIMA_APROBADO = 5.0;
    public static final double NOTA_MAXIMA = 10.0;
    public static final double NOTA_MINIMA = 0.0;
    public static final int MAXIMO_CREDITOS = 60;

    // --- Campos de instancia ---
    private String nombre;
    private String email;
    private double notaMedia;

    // --- Campo estatico (no constante) ---
    private static int totalAlumnos = 0;

    public Alumno(String nombre, String email) {
        this.nombre = nombre;
        this.email = email;
        this.notaMedia = 0.0;
        totalAlumnos++;
    }

    // --- Getters ---
    public String getNombre() { return nombre; }
    public double getNotaMedia() { return notaMedia; }
    public static int getTotalAlumnos() { return totalAlumnos; }

    // --- Setter con validacion usando constantes ---
    public void setNotaMedia(double notaMedia) {
        if (notaMedia < NOTA_MINIMA || notaMedia > NOTA_MAXIMA) {
            throw new IllegalArgumentException(
                "La nota debe estar entre " + NOTA_MINIMA + " y " + NOTA_MAXIMA
            );
        }
        this.notaMedia = notaMedia;
    }

    public boolean estaAprobado() {
        return notaMedia >= NOTA_MINIMA_APROBADO;
    }

    public static void main(String[] args) {
        System.out.println("Nota minima aprobado: " + Alumno.NOTA_MINIMA_APROBADO);
        System.out.println("Max creditos: " + Alumno.MAXIMO_CREDITOS);

        Alumno a = new Alumno("Ana", "ana@email.com");
        a.setNotaMedia(8.5);
        System.out.println(a.getNombre() + ": " + a.getCalificacion());
    }

    public String getCalificacion() {
        if (notaMedia >= 9) return "Sobresaliente";
        if (notaMedia >= 7) return "Notable";
        if (notaMedia >= 5) return "Aprobado";
        return "Suspenso";
    }
}

public class CalculadoraNotas {
    public static final double NOTA_APROBADO = 5.0;
    public static final double NOTA_MAXIMA = 10.0;
    public static final String[] CALIFICACIONES = {
        "Suspenso", "Aprobado", "Notable", "Sobresaliente"
    };

    // Metodo estatico: no necesita objeto
    public static String calcularCalificacion(double nota) {
        if (nota >= 9) return CALIFICACIONES[3];
        if (nota >= 7) return CALIFICACIONES[2];
        if (nota >= NOTA_APROBADO) return CALIFICACIONES[1];
        return CALIFICACIONES[0];
    }

    public static boolean estaAprobado(double nota) {
        return nota >= NOTA_APROBADO;
    }

    public static double calcularMedia(double[] notas) {
        double suma = 0;
        for (double nota : notas) {
            suma += nota;
        }
        return suma / notas.length;
    }

    public static void main(String[] args) {
        double[] notas = {8.5, 7.0, 9.2, 4.5, 6.8};

        for (double nota : notas) {
            System.out.printf("Nota: %.1f -> %s (Aprobado: %s)%n",
                nota,
                calcularCalificacion(nota),
                estaAprobado(nota) ? "Si" : "No");
        }

        double media = calcularMedia(notas);
        System.out.printf("\nMedia: %.2f -> %s%n", media, calcularCalificacion(media));
    }
}

