public class StringUtils {
    public static boolean esVacia(String s) {
        return s == null || s.isBlank();
    }

    public static String capitalizar(String s) {
        if (esVacia(s)) return s;
        return s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
    }

    public static boolean contiene(String s, String sub) {
        if (s == null || sub == null) return false;
        return s.contains(sub);
    }

    public static String repetir(String s, int n) {
        if (s == null || n <= 0) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(s);
        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println(capitalizar("hola"));     // Hola
        System.out.println(contiene("Java", "av"));  // true
        System.out.println(repetir("-", 10));         // ----------
    }
}

